// Hand-written Phase 3 addition. NOT regenerated by CLI Printing Press —
// safe to edit. Kept in its own file (rather than store.go) because
// store.go is overwritten on regen.

package store

import (
	"database/sql"
	"fmt"
	"strings"
	"time"
)

// FlipkartProduct is a row of the flipkart_products table: the latest known
// detail-page snapshot for a product, keyed by the Flipkart `pid`.
type FlipkartProduct struct {
	ProductID    string
	URL          string
	Title        string
	Brand        string
	Price        float64
	Currency     string
	Availability string
	Rating       float64
	ReviewCount  int
	SKU          string
	Category     string
	MRP          float64
	DiscountPct  float64
	FetchedAt    time.Time
}

// FlipkartPriceHistoryRow is a row of the flipkart_price_history table.
type FlipkartPriceHistoryRow struct {
	ID         int64
	ProductID  string
	Price      float64
	ObservedAt time.Time
}

// FlipkartWatch is a row of the flipkart_watches table.
type FlipkartWatch struct {
	ProductID     string
	URL           string
	Threshold     float64
	AddedAt       time.Time
	LastCheckedAt time.Time // zero value means never checked
}

// FlipkartOffer is a row of the flipkart_offers table (a bank/card offer
// observed on a product's detail page at a point in time).
type FlipkartOffer struct {
	ProductID   string
	AmountOff   float64
	Description string
	ObservedAt  time.Time
}

// FlipkartSnapshotRow is a row of the flipkart_search_snapshots table.
type FlipkartSnapshotRow struct {
	Position  int    `json:"position"`
	ProductID string `json:"product_id,omitempty"`
	Title     string `json:"title"`
	URL       string `json:"url"`
}

// EnsureFlipkartSchema creates the Phase 3 tables/indexes if they don't
// already exist. Idempotent — safe to call once per command invocation
// before use, per Printing Press convention (new tables live in their own
// migration file rather than store.go's migrate(), which is overwritten on
// regeneration).
func (s *Store) EnsureFlipkartSchema() error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()

	stmts := []string{
		`CREATE TABLE IF NOT EXISTS flipkart_products (
			product_id TEXT PRIMARY KEY,
			url TEXT NOT NULL,
			title TEXT,
			brand TEXT,
			price REAL,
			currency TEXT,
			availability TEXT,
			rating REAL,
			review_count INTEGER,
			sku TEXT,
			category TEXT,
			mrp REAL,
			discount_pct REAL,
			fetched_at TIMESTAMP
		)`,
		`CREATE TABLE IF NOT EXISTS flipkart_price_history (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			product_id TEXT NOT NULL,
			price REAL,
			observed_at TIMESTAMP
		)`,
		`CREATE INDEX IF NOT EXISTS idx_flipkart_price_history_product ON flipkart_price_history(product_id, observed_at)`,
		`CREATE TABLE IF NOT EXISTS flipkart_watches (
			product_id TEXT PRIMARY KEY,
			url TEXT NOT NULL,
			threshold REAL,
			added_at TIMESTAMP,
			last_checked_at TIMESTAMP
		)`,
		`CREATE TABLE IF NOT EXISTS flipkart_offers (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			product_id TEXT NOT NULL,
			amount_off REAL,
			description TEXT,
			observed_at TIMESTAMP
		)`,
		`CREATE INDEX IF NOT EXISTS idx_flipkart_offers_product ON flipkart_offers(product_id)`,
		`CREATE TABLE IF NOT EXISTS flipkart_search_snapshots (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			query TEXT NOT NULL,
			position INTEGER,
			product_id TEXT,
			title TEXT,
			url TEXT,
			fetched_at TIMESTAMP
		)`,
		`CREATE INDEX IF NOT EXISTS idx_flipkart_search_snapshots_query ON flipkart_search_snapshots(query, fetched_at)`,
		`CREATE TABLE IF NOT EXISTS flipkart_feed_cursors (
			category TEXT PRIMARY KEY,
			from_version TEXT,
			updated_at TIMESTAMP
		)`,
	}
	for _, stmt := range stmts {
		if _, err := s.db.Exec(stmt); err != nil {
			return fmt.Errorf("flipkart schema migration failed: %w", err)
		}
	}
	return nil
}

// UpsertFlipkartProduct inserts or refreshes the detail-page fields for a
// product. Deliberately does not touch mrp/discount_pct — those are owned
// by UpsertFlipkartProductMRP (populated by `product offers`, which may run
// before or after `product get`) so neither command clobbers the other's data.
func (s *Store) UpsertFlipkartProduct(p FlipkartProduct) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, err := s.db.Exec(`
		INSERT INTO flipkart_products (product_id, url, title, brand, price, currency, availability, rating, review_count, sku, category, fetched_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(product_id) DO UPDATE SET
			url = excluded.url,
			title = excluded.title,
			brand = excluded.brand,
			price = excluded.price,
			currency = excluded.currency,
			availability = excluded.availability,
			rating = excluded.rating,
			review_count = excluded.review_count,
			sku = excluded.sku,
			category = excluded.category,
			fetched_at = excluded.fetched_at
	`, p.ProductID, p.URL, p.Title, p.Brand, p.Price, p.Currency, p.Availability, p.Rating, p.ReviewCount, p.SKU, p.Category, p.FetchedAt)
	return err
}

// UpsertFlipkartProductMRP records the resolved MRP/discount for a product,
// creating a minimal row if `product get` hasn't run yet for this pid. Does
// not touch title/brand/etc so it can't clobber richer data recorded by
// UpsertFlipkartProduct.
func (s *Store) UpsertFlipkartProductMRP(productID, url string, mrp, discountPct float64) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, err := s.db.Exec(`
		INSERT INTO flipkart_products (product_id, url, mrp, discount_pct, fetched_at)
		VALUES (?, ?, ?, ?, ?)
		ON CONFLICT(product_id) DO UPDATE SET
			mrp = excluded.mrp,
			discount_pct = excluded.discount_pct
	`, productID, url, mrp, discountPct, time.Now())
	return err
}

// GetFlipkartProduct returns the stored snapshot for a product, if any.
func (s *Store) GetFlipkartProduct(productID string) (*FlipkartProduct, error) {
	var p FlipkartProduct
	var fetchedAt sql.NullTime
	err := s.db.QueryRow(`
		SELECT product_id, url, title, brand, price, currency, availability, rating, review_count, sku, category, mrp, discount_pct, fetched_at
		FROM flipkart_products WHERE product_id = ?
	`, productID).Scan(&p.ProductID, &p.URL, &p.Title, &p.Brand, &p.Price, &p.Currency, &p.Availability, &p.Rating, &p.ReviewCount, &p.SKU, &p.Category, &p.MRP, &p.DiscountPct, &fetchedAt)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if fetchedAt.Valid {
		p.FetchedAt = fetchedAt.Time
	}
	return &p, nil
}

// InsertFlipkartPriceHistory appends a price observation for a product.
func (s *Store) InsertFlipkartPriceHistory(productID string, price float64, observedAt time.Time) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, err := s.db.Exec(`INSERT INTO flipkart_price_history (product_id, price, observed_at) VALUES (?, ?, ?)`, productID, price, observedAt)
	return err
}

// LatestFlipkartPriceHistory returns up to n most recent price observations
// for a product, newest first.
func (s *Store) LatestFlipkartPriceHistory(productID string, n int) ([]FlipkartPriceHistoryRow, error) {
	if n <= 0 {
		n = 2
	}
	rows, err := s.db.Query(`
		SELECT id, product_id, price, observed_at FROM flipkart_price_history
		WHERE product_id = ? ORDER BY observed_at DESC, id DESC LIMIT ?
	`, productID, n)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []FlipkartPriceHistoryRow
	for rows.Next() {
		var r FlipkartPriceHistoryRow
		if err := rows.Scan(&r.ID, &r.ProductID, &r.Price, &r.ObservedAt); err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// UpsertFlipkartWatch inserts a new watch or updates the URL/threshold of an
// existing one for the same product_id.
func (s *Store) UpsertFlipkartWatch(productID, url string, threshold float64, addedAt time.Time) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, err := s.db.Exec(`
		INSERT INTO flipkart_watches (product_id, url, threshold, added_at)
		VALUES (?, ?, ?, ?)
		ON CONFLICT(product_id) DO UPDATE SET url = excluded.url, threshold = excluded.threshold
	`, productID, url, threshold, addedAt)
	return err
}

// ListFlipkartWatches returns every configured watch, oldest first.
func (s *Store) ListFlipkartWatches() ([]FlipkartWatch, error) {
	rows, err := s.db.Query(`SELECT product_id, url, threshold, added_at, last_checked_at FROM flipkart_watches ORDER BY added_at`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []FlipkartWatch
	for rows.Next() {
		var w FlipkartWatch
		var lastChecked sql.NullTime
		if err := rows.Scan(&w.ProductID, &w.URL, &w.Threshold, &w.AddedAt, &lastChecked); err != nil {
			return nil, err
		}
		if lastChecked.Valid {
			w.LastCheckedAt = lastChecked.Time
		}
		out = append(out, w)
	}
	return out, rows.Err()
}

// UpdateFlipkartWatchLastChecked stamps last_checked_at for a watched product.
func (s *Store) UpdateFlipkartWatchLastChecked(productID string, t time.Time) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, err := s.db.Exec(`UPDATE flipkart_watches SET last_checked_at = ? WHERE product_id = ?`, t, productID)
	return err
}

// ReplaceFlipkartOffers replaces all stored bank-offer rows for a product
// with a fresh scan. Delete-then-insert (rather than append-only) keeps the
// table holding only the latest observed offers per product, so aggregation
// queries (offers best-card) don't double-count across repeated scans.
func (s *Store) ReplaceFlipkartOffers(productID string, offers []FlipkartOffer, observedAt time.Time) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`DELETE FROM flipkart_offers WHERE product_id = ?`, productID); err != nil {
		return err
	}
	for _, o := range offers {
		if _, err := tx.Exec(`INSERT INTO flipkart_offers (product_id, amount_off, description, observed_at) VALUES (?, ?, ?, ?)`,
			productID, o.AmountOff, o.Description, observedAt); err != nil {
			return err
		}
	}
	return tx.Commit()
}

// FlipkartOffersForProducts returns all stored offer rows across the given
// product IDs. Used by `offers best-card` to aggregate stacked savings
// across a specific shortlist of products.
func (s *Store) FlipkartOffersForProducts(productIDs []string) ([]FlipkartOffer, error) {
	if len(productIDs) == 0 {
		return nil, nil
	}
	placeholders := make([]string, len(productIDs))
	args := make([]any, len(productIDs))
	for i, id := range productIDs {
		placeholders[i] = "?"
		args[i] = id
	}
	query := fmt.Sprintf(`SELECT product_id, amount_off, description, observed_at FROM flipkart_offers WHERE product_id IN (%s)`, strings.Join(placeholders, ","))
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []FlipkartOffer
	for rows.Next() {
		var o FlipkartOffer
		if err := rows.Scan(&o.ProductID, &o.AmountOff, &o.Description, &o.ObservedAt); err != nil {
			return nil, err
		}
		out = append(out, o)
	}
	return out, rows.Err()
}

// LatestFlipkartSearchSnapshot returns the most recently stored snapshot for
// a query string, along with the fetched_at timestamp shared by that batch
// of rows. Returns (nil, zero-time, nil) when no snapshot has been stored yet.
//
// Deliberately a single query with no separate fetched_at correlation step:
// because ReplaceFlipkartSearchSnapshot always deletes the prior batch for
// a query before inserting the new one, every row currently stored for a
// given query already belongs to exactly one batch. An earlier version of
// this function first read the batch's fetched_at via one query and then
// matched on it via `WHERE fetched_at = ?` in a second — but modernc.org/
// sqlite round-trips a scanned time.Time without its monotonic-clock
// reading, while the original INSERT's argument carried one, so the two
// string encodings silently failed to compare equal and the second query
// always returned zero rows (making every run after the first look like
// "no prior snapshot"). Reading the whole batch in one pass sidesteps that
// entirely.
func (s *Store) LatestFlipkartSearchSnapshot(query string) ([]FlipkartSnapshotRow, time.Time, error) {
	rows, err := s.db.Query(`
		SELECT position, product_id, title, url, fetched_at FROM flipkart_search_snapshots
		WHERE query = ? ORDER BY position
	`, query)
	if err != nil {
		return nil, time.Time{}, err
	}
	defer rows.Close()
	var out []FlipkartSnapshotRow
	var fetchedAt time.Time
	for rows.Next() {
		var r FlipkartSnapshotRow
		var pid sql.NullString
		if err := rows.Scan(&r.Position, &pid, &r.Title, &r.URL, &fetchedAt); err != nil {
			return nil, time.Time{}, err
		}
		r.ProductID = pid.String
		out = append(out, r)
	}
	return out, fetchedAt, rows.Err()
}

// ReplaceFlipkartSearchSnapshot deletes any prior snapshot rows for query
// and inserts the new batch, all stamped with the same fetchedAt so a
// subsequent LatestFlipkartSearchSnapshot call retrieves them as one group.
func (s *Store) ReplaceFlipkartSearchSnapshot(query string, items []FlipkartSnapshotRow, fetchedAt time.Time) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`DELETE FROM flipkart_search_snapshots WHERE query = ?`, query); err != nil {
		return err
	}
	for _, it := range items {
		if _, err := tx.Exec(`
			INSERT INTO flipkart_search_snapshots (query, position, product_id, title, url, fetched_at)
			VALUES (?, ?, ?, ?, ?, ?)
		`, query, it.Position, it.ProductID, it.Title, it.URL, fetchedAt); err != nil {
			return err
		}
	}
	return tx.Commit()
}

// GetFlipkartFeedCursor returns the stored from_version for a category feed,
// and whether one has been stored yet.
func (s *Store) GetFlipkartFeedCursor(category string) (string, bool, error) {
	var v string
	err := s.db.QueryRow(`SELECT from_version FROM flipkart_feed_cursors WHERE category = ?`, category).Scan(&v)
	if err == sql.ErrNoRows {
		return "", false, nil
	}
	if err != nil {
		return "", false, err
	}
	return v, true, nil
}

// SetFlipkartFeedCursor stores the from_version to use on the next feed
// digest run for a category.
func (s *Store) SetFlipkartFeedCursor(category, fromVersion string) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, err := s.db.Exec(`
		INSERT INTO flipkart_feed_cursors (category, from_version, updated_at)
		VALUES (?, ?, ?)
		ON CONFLICT(category) DO UPDATE SET from_version = excluded.from_version, updated_at = excluded.updated_at
	`, category, fromVersion, time.Now())
	return err
}
